           Xj[k] = Xj[k-1] + dj[q];
           mark[Xi[k]][Xj[k]] = true;// update
           if(k == N*N) solution();
           else TRY(k+1);
           mark[Xi[k]][Xj[k]] = false;// recover
       }
    }
}
